const canonical = (v) => Array.isArray(v) ? `[${v.map(canonical).join(",")}]` : v && typeof v === "object" ? `{${Object.keys(v).sort().map((k) => `${JSON.stringify(k)}:${canonical(v[k])}`).join(",")}}` : JSON.stringify(v);
const digest = (v) => createHash("sha256").update(typeof v === "string" ? v : canonical(v)).digest("hex");
const nowIso = (config) => config.now().toISOString();
const londonMonth = (date) => { const parts=Object.fromEntries(new Intl.DateTimeFormat("en-GB",{timeZone:"Europe/London",year:"numeric",month:"2-digit"}).formatToParts(date).map(part=>[part.type,part.value])); return `${parts.year}-${parts.month}`; };
const money = (v, zero = false) => { if (!Number.isSafeInteger(v) || v < (zero ? 0 : 1) || v > VALIDATION.priceMaxMinor) throw new HttpError(400, "VALIDATION_ERROR", "Amount is invalid"); return v; };
const key = (req) => text(req.headers["idempotency-key"], 1, VALIDATION.idempotencyKeyMax, "Idempotency-Key");
const json = (v, fallback = []) => { try { return JSON.parse(v ?? JSON.stringify(fallback)); } catch { return fallback; } };
const cursor = (url) => { const v = url.searchParams.get("cursor"); if (v && !/^\d+$/.test(v)) throw new HttpError(400, "VALIDATION_ERROR", "Cursor is invalid"); return Number(v ?? 0); };
const page = (rows, offset, size = 50) => ({ items: rows.slice(0, size), nextCursor: rows.length > size ? String(offset + size) : null });

function operationDto(r) { return { id:r.id, operationKey:r.operation_key, restaurantId:r.restaurant_id, orderId:r.order_id, kind:r.kind, status:r.status, amountMinor:r.amount_minor, currency:r.currency, providerMode:r.provider_mode, providerReference:r.provider_reference, error:r.error, metadata:json(r.metadata,{}), createdAt:r.created_at, updatedAt:r.updated_at }; }
function postingDto(r) { return { id:r.id, operationKey:r.operation_key, groupId:r.group_id, account:r.account, direction:r.direction, amountMinor:r.amount_minor, currency:r.currency, sourceType:r.source_type, sourceId:r.source_id, providerMode:r.provider_mode, createdAt:r.created_at }; }
function addOperation(db, { operationKey, restaurantId, orderId = null, kind, status, amountMinor, providerMode = "local_simulator", metadata = {}, now }) {
  db.prepare("INSERT OR IGNORE INTO marketplace_operations VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?)").run(randomUUID(),operationKey,restaurantId,orderId,kind,status,amountMinor,"GBP",providerMode,null,null,JSON.stringify(metadata),now,now);
  return db.prepare("SELECT * FROM marketplace_operations WHERE operation_key=?").get(operationKey);
}
function postBalanced(db, op, debit, credit, amount, sourceType, sourceId, now) {
  if (!amount || db.prepare("SELECT 1 FROM journal_postings WHERE operation_key=? LIMIT 1").get(op.operation_key)) return;
  const group=randomUUID(); for (const [account,direction] of [[debit,"debit"],[credit,"credit"]]) db.prepare("INSERT INTO journal_postings VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)").run(randomUUID(),group,op.operation_key,op.restaurant_id,op.order_id,account,direction,amount,"GBP",sourceType,sourceId,op.provider_mode,now);
}

export function recordMarketplaceAcceptance(db, order, now, config = null) {
  const stripePayment=order.payment_method==="card"?db.prepare("SELECT * FROM stripe_order_payments WHERE order_id=?").get(order.id):null,providerMode=stripePayment?.provider_mode??config?.paymentProviderMode??"local_simulator";
  const capture=addOperation(db,{operationKey:`order:${order.id}:capture`,restaurantId:order.restaurant_id,orderId:order.id,kind:order.payment_method==="cash"?"cash_order_accepted":"payment_capture",status:"confirmed",amountMinor:order.total_minor,providerMode,now,metadata:{paymentMethod:order.payment_method}});
  if(order.payment_method!=="cash")postBalanced(db,capture,"customer_funds","order_captured",order.total_minor,"order",order.id,now);
  const commission=addOperation(db,{operationKey:`order:${order.id}:commission`,restaurantId:order.restaurant_id,orderId:order.id,kind:order.payment_method==="cash"?"cash_commission_receivable":"commission",status:"confirmed",amountMinor:order.commission_minor,providerMode,now,metadata:{rateBasisPoints:order.contract_rate_bps,base:order.commission_base??"food",policyVersion:order.contract_policy_version}});
  postBalanced(db,commission,"merchant_earnings","platform_commission",order.commission_minor,"order",order.id,now);
  if(order.payment_method!=="cash"&&order.payment_method!=="card"){
    const providerCost=20+Number((BigInt(order.total_minor)*150n+9999n)/10000n);
    const cost=addOperation(db,{operationKey:`order:${order.id}:provider-cost`,restaurantId:order.restaurant_id,orderId:order.id,kind:"provider_cost",status:"confirmed",amountMinor:providerCost,now,metadata:{simulatorFormula:"20p + 1.5% rounded up",borneBy:"platform"}});
    postBalanced(db,cost,"provider_cost_expense","provider_payable",providerCost,"order",order.id,now);
  }
  if(order.payment_method==="card"&&stripePayment?.provider_cost_minor){const cost=addOperation(db,{operationKey:`order:${order.id}:provider-cost`,restaurantId:order.restaurant_id,orderId:order.id,kind:"provider_cost",status:"confirmed",amountMinor:stripePayment.provider_cost_minor,providerMode,now,metadata:{borneBy:"platform",source:"stripe_balance_transaction"}});postBalanced(db,cost,"provider_cost_expense","provider_payable",stripePayment.provider_cost_minor,"order",order.id,now);}
  const receipt=JSON.stringify(receiptV1(db,order));
  for(const printer of db.prepare("SELECT * FROM restaurant_printers WHERE restaurant_id=? AND enabled=1 AND revoked_at IS NULL").all(order.restaurant_id)) db.prepare("INSERT OR IGNORE INTO device_print_jobs(id,printer_id,order_id,operation_key,receipt,status,manual_reprint,attempt,created_at,updated_at) VALUES(?,?,?,?,?,'queued',0,0,?,?)").run(randomUUID(),printer.id,order.id,`order:${order.id}:printer:${printer.id}:original`,receipt,now,now);
}
export function recordMarketplaceCompletion(db, order, now, config = null) {
  const refunds=db.prepare("SELECT COALESCE(SUM(food_amount_minor+delivery_amount_minor),0) total,COALESCE(SUM(commission_reversal_minor),0) reversal FROM refunds WHERE order_id=?").get(order.id);
  const netCommission=Math.max(0,order.commission_minor-refunds.reversal);
  const amount=Math.max(0,order.total_minor-refunds.total-netCommission);
  const cash=order.payment_method==="cash";
  const card=order.payment_method==="card",providerMode=card?db.prepare("SELECT provider_mode FROM stripe_order_payments WHERE order_id=?").get(order.id)?.provider_mode??"stripe_test":config?.paymentProviderMode??"local_simulator",op=addOperation(db,{operationKey:`order:${order.id}:settlement-eligible`,restaurantId:order.restaurant_id,orderId:order.id,kind:cash?"cash_sale_recorded":"settlement_eligibility",status:cash?"held":"confirmed",amountMinor:cash?order.total_minor:amount,providerMode,now,metadata:{cashExcluded:cash,refundsMinor:refunds.total,commissionReversalMinor:refunds.reversal}});
  if(cash)postBalanced(db,op,"customer_cash","merchant_cash_sales",order.total_minor,"order",order.id,now);else{postBalanced(db,op,"order_captured","merchant_available",amount,"order",order.id,now);if(!card)db.prepare("INSERT OR IGNORE INTO marketplace_worker_jobs(id,kind,entity_id,operation_key,status,lease_owner,lease_expires_at,attempts,payload,error,available_at,created_at,updated_at) VALUES(?,?,?,?,'queued',NULL,NULL,0,?,NULL,?,?,?)").run(randomUUID(),"transfer_eligibility",order.id,`transfer:${order.id}`,JSON.stringify({orderId:order.id,operationId:op.id}),now,now,now);}
}

function financeOrder(db,row){const refunds=db.prepare("SELECT COALESCE(SUM(food_amount_minor+delivery_amount_minor),0) n,COALESCE(SUM(commission_reversal_minor),0) reversal FROM refunds WHERE order_id=?").get(row.id);const settlement=db.prepare("SELECT status FROM marketplace_operations WHERE operation_key=?").get(`order:${row.id}:settlement-eligible`),commission=Math.max(0,row.commission_minor-refunds.reversal),provider=db.prepare("SELECT COALESCE(SUM(amount_minor),0)n FROM marketplace_operations WHERE order_id=? AND kind='provider_cost' AND status='confirmed'").get(row.id).n,stripe=row.payment_method==="card"?db.prepare("SELECT provider_mode FROM stripe_order_payments WHERE order_id=?").get(row.id):null;const refunded=refunds.n>=row.total_minor;return{orderId:row.id,restaurantId:row.restaurant_id,orderTotalMinor:row.total_minor,foodMinor:row.subtotal_minor,deliveryMinor:row.delivery_fee_minor,refundsMinor:refunds.n,commissionMinor:commission,providerCostMinor:provider,merchantNetMinor:Math.max(0,row.total_minor-refunds.n-commission),paymentMethod:row.payment_method,paymentState:row.payment_status,settlementState:refunded?"refunded":settlement?.status??"pending",holdReason:refunded?"fully_refunded":row.payment_method==="cash"?"cash_not_bank_payout_eligible":row.status==="rejected"?"order_rejected":null,policySnapshot:{rateBasisPoints:row.contract_rate_bps,base:row.commission_base??"food",version:row.contract_policy_version},providerMode:stripe?.provider_mode??"local_simulator",createdAt:row.created_at};}
function dateRange(url) {
  return parseLondonDateRange(url);
}
function inRange(row,range){return inDateRange(row,range);}
function summary(db,id,url=null){return buildFinanceSummary(db,id,url);}
function policyDto(r){return{id:r.id,rateBasisPoints:r.rate_bps,base:r.commission_base,startsAt:r.starts_at,endsAt:r.ends_at,durationMonths:r.duration_months,version:r.version,developmentAssumption:Boolean(r.development_assumption),acceptedAt:r.accepted_at};}
function proposedPolicy(id,config){const start=config.now(),end=new Date(start),hex=digest(`commission-policy:${id}:development-v1`).slice(0,32);end.setUTCMonth(end.getUTCMonth()+24);return{id:`${hex.slice(0,8)}-${hex.slice(8,12)}-4${hex.slice(13,16)}-8${hex.slice(17,20)}-${hex.slice(20)}`,restaurant_id:id,rate_bps:700,commission_base:DEFAULT_COMMISSION_BASE,starts_at:start.toISOString(),ends_at:end.toISOString(),duration_months:24,version:"development-v1",development_assumption:1,accepted_at:null,accepted_by_user_id:null,created_at:start.toISOString()};}
function currentPolicy(db,id,config){return db.prepare("SELECT * FROM commission_policies WHERE restaurant_id=? ORDER BY created_at DESC LIMIT 1").get(id)??proposedPolicy(id,config);}
function printerDto(r){return{id:r.id,restaurantId:r.restaurant_id,name:r.name,macAddress:r.mac_address??null,ipAddress:r.ip_address??null,enabled:Boolean(r.enabled),revoked:Boolean(r.revoked_at),createdAt:r.created_at,updatedAt:r.updated_at};}
function restaurantPrinterState(db, restaurantId, config) {
  const devices = new Map(db.prepare("SELECT printer_id,COUNT(*) AS paired_device_count,MAX(last_seen_at) AS last_seen_at FROM printer_devices WHERE restaurant_id=? AND revoked_at IS NULL GROUP BY printer_id").all(restaurantId).map(row => [row.printer_id, row]));
  const jobs = new Map();
  for (const row of db.prepare("SELECT j.printer_id,j.status,COUNT(*) AS count FROM device_print_jobs j JOIN restaurant_printers p ON p.id=j.printer_id WHERE p.restaurant_id=? GROUP BY j.printer_id,j.status").all(restaurantId)) {
    if (!jobs.has(row.printer_id)) jobs.set(row.printer_id, { queued: 0, claimed: 0, printed: 0, failed: 0, uncertain: 0 });
    if (Object.hasOwn(jobs.get(row.printer_id), row.status)) jobs.get(row.printer_id)[row.status] = row.count;
  }
  const cutoff = config.now().getTime() - 60000;
  return db.prepare("SELECT * FROM restaurant_printers WHERE restaurant_id=? ORDER BY created_at,id").all(restaurantId).map(row => {
    const device = devices.get(row.id), pairedDeviceCount = device?.paired_device_count ?? 0, lastSeenAt = device?.last_seen_at ?? null;
    const status = row.revoked_at ? "revoked" : !row.enabled ? "disabled" : !pairedDeviceCount ? "awaiting_device" : lastSeenAt && Date.parse(lastSeenAt) >= cutoff ? "online" : "offline";
    return { ...printerDto(row), status, lastSeenAt, pairedDeviceCount, jobs: jobs.get(row.id) ?? { queued: 0, claimed: 0, printed: 0, failed: 0, uncertain: 0 } };
  });
}
function mandateDto(r){return r?{id:r.id,restaurantId:r.restaurant_id,status:r.status,providerMode:r.provider_mode,createdAt:r.created_at,updatedAt:r.updated_at}:null;}

