async function mutateMandate({req,res,db,config,session,id}){
  if(["stripe_test","stripe_live"].includes(config.paymentProviderMode))throw new HttpError(501,"BACS_NOT_CONNECTED","Cash commission mandate collection is not connected to Stripe yet");
  const user=requireRestaurantOwner(db,session,id),body=await readJson(req,config.bodyLimit);exactObject(body,["action"]);
  if(!["create","authorize_simulation","revoke"].includes(body.action))throw new HttpError(400,"VALIDATION_ERROR","Action is invalid");
  const idempotencyKey=key(req),operationKey=`mandate:${id}:${user.id}:${idempotencyKey}`,requestHash=digest({restaurantId:id,action:body.action}),now=nowIso(config);
  const row=withTransaction(db,()=>{
    const replay=db.prepare("SELECT * FROM marketplace_operations WHERE operation_key=?").get(operationKey);
    if(replay){if(json(replay.metadata,{}).requestHash!==requestHash)throw new HttpError(409,"IDEMPOTENCY_CONFLICT","Idempotency key was already used");return db.prepare("SELECT * FROM cash_mandates WHERE restaurant_id=?").get(id);}
    let mandate=db.prepare("SELECT * FROM cash_mandates WHERE restaurant_id=?").get(id);
    if(!mandate){if(body.action!=="create")throw new HttpError(409,"MANDATE_REQUIRED","Create the local simulation mandate first");db.prepare("INSERT INTO cash_mandates(id,restaurant_id,status,provider_mode,operation_key,provider_reference,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?)").run(randomUUID(),id,"created","local_simulator",operationKey,null,now,now);mandate=db.prepare("SELECT * FROM cash_mandates WHERE restaurant_id=?").get(id);}
    else if(mandate.status==="revoked")throw new HttpError(409,"MANDATE_REVOKED","A revoked mandate cannot be reauthorised");
    else if(body.action==="authorize_simulation")db.prepare("UPDATE cash_mandates SET status='authorised',updated_at=? WHERE id=?").run(now,mandate.id);
    else if(body.action==="revoke")db.prepare("UPDATE cash_mandates SET status='revoked',updated_at=? WHERE id=?").run(now,mandate.id);
    addOperation(db,{operationKey,restaurantId:id,kind:"cash_mandate_action",status:"confirmed",amountMinor:0,now,metadata:{requestHash,action:body.action,simulation:true}});
    return db.prepare("SELECT * FROM cash_mandates WHERE restaurant_id=?").get(id);
  });
  return sendJson(res,200,{data:mandateDto(row)});
}
async function collectCash({req,res,db,config,session,id}){
  if(["stripe_test","stripe_live"].includes(config.paymentProviderMode))throw new HttpError(501,"BACS_NOT_CONNECTED","Cash commission collection is not connected to Stripe yet");
  requireRestaurantOwner(db,session,id);const body=await readJson(req,config.bodyLimit);exactObject(body,["amountMinor","outcome"]);
  const amount=money(body.amountMinor),outcome=body.outcome??"succeeded";if(!["succeeded","failed","delayed"].includes(outcome))throw new HttpError(400,"VALIDATION_ERROR","Outcome is invalid");
  const operationKey=`cash-collection:${id}:${key(req)}`,requestHash=digest({restaurantId:id,amount,outcome}),now=nowIso(config);
  const row=withTransaction(db,()=>{
    const mandate=db.prepare("SELECT * FROM cash_mandates WHERE restaurant_id=? AND status='authorised'").get(id);if(!mandate)throw new HttpError(409,"MANDATE_NOT_AUTHORISED","Cash collection mandate is not authorised");
    const existing=db.prepare("SELECT * FROM cash_collections WHERE operation_key=?").get(operationKey);
    if(existing){const prior=db.prepare("SELECT metadata FROM marketplace_operations WHERE operation_key=?").get(operationKey);if(json(prior?.metadata,{}).requestHash!==requestHash)throw new HttpError(409,"IDEMPOTENCY_CONFLICT","Idempotency key was already used");return existing;}
    const outstanding=summary(db,id).cashCommissionOutstandingMinor;if(amount>outstanding)throw new HttpError(409,"COLLECTION_EXCEEDS_OUTSTANDING","Collection exceeds outstanding commission");
    const collectionId=randomUUID();db.prepare("INSERT INTO cash_collections(id,restaurant_id,mandate_id,operation_key,amount_minor,status,provider_mode,failure,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?)").run(collectionId,id,mandate.id,operationKey,amount,outcome,"local_simulator",outcome==="failed"?"Simulated insufficient funds":null,now,now);
    const op=addOperation(db,{operationKey,restaurantId:id,kind:"cash_commission_collection",status:outcome==="succeeded"?"confirmed":outcome,amountMinor:amount,now,metadata:{requestHash,simulation:true}});if(outcome==="succeeded")postBalanced(db,op,"cash_collection","cash_commission_receivable",amount,"cash_collection",collectionId,now);if(outcome==="delayed")db.prepare("INSERT OR IGNORE INTO marketplace_worker_jobs(id,kind,entity_id,operation_key,status,lease_owner,lease_expires_at,attempts,payload,error,available_at,created_at,updated_at) VALUES(?,?,?,?,'queued',NULL,NULL,0,?,NULL,?,?,?)").run(randomUUID(),"cash_collection_reconcile",collectionId,`reconcile:${operationKey}`,JSON.stringify({collectionId}),now,now,now);
    return db.prepare("SELECT * FROM cash_collections WHERE id=?").get(collectionId);
  });
  return sendJson(res,201,{data:{id:row.id,status:row.status,amountMinor:row.amount_minor,providerMode:row.provider_mode,failure:row.failure,createdAt:row.created_at}});
}
async function providerAccount({req,res,db,config,session,id}){
  if(config.paymentProviderMode!=="local_simulator")throw new HttpError(409,"STRIPE_SETUP_REQUIRED","Use Stripe setup for verified restaurant onboarding");
  const user=requireRestaurantOwner(db,session,id),b=await readJson(req,config.bodyLimit);
  exactObject(b,["action"]);if(!["create_test","refresh"].includes(b.action))throw new HttpError(400,"VALIDATION_ERROR","Action is invalid");
  const prior=db.prepare("SELECT * FROM provider_accounts WHERE restaurant_id=?").get(id),now=nowIso(config);
  let result={status:"pending",providerReference:prior?.provider_reference,capabilities:[],requirements:["local_simulation_only"]};
  if(config.paymentProviderMode==="stripe_test"){
    if(!config.paymentProvider)throw new HttpError(503,"PROVIDER_NOT_CONFIGURED","Stripe test provider is not configured");
    if(b.action==="create_test"){
      if(prior?.provider_reference)result=await config.paymentProvider.refreshConnectedAccount({accountId:prior.provider_reference});
      else result=await config.paymentProvider.createConnectedAccount({restaurantId:id,email:user.email,idempotencyKey:key(req)});
    }else{
      if(!prior?.provider_reference)throw new HttpError(409,"PROVIDER_ACCOUNT_REQUIRED","Create the test provider account first");
      result=await config.paymentProvider.refreshConnectedAccount({accountId:prior.provider_reference});
    }
  }
  const status=result.status==="confirmed"?"enabled":result.status==="failed"?"restricted":"pending";
  withTransaction(db,()=>db.prepare("INSERT INTO provider_accounts VALUES(?,?,?,?,?,?,?,?,?) ON CONFLICT(restaurant_id) DO UPDATE SET provider_mode=excluded.provider_mode,status=excluded.status,capabilities=excluded.capabilities,requirements=excluded.requirements,provider_reference=COALESCE(excluded.provider_reference,provider_accounts.provider_reference),updated_at=excluded.updated_at").run(randomUUID(),id,config.paymentProviderMode,status,JSON.stringify(result.capabilities??[]),JSON.stringify(result.requirements??(result.errorCode?[result.errorCode]:[])),result.providerReference??null,now,now));
  return sendJson(res,200,{data:providerDto(db.prepare("SELECT * FROM provider_accounts WHERE restaurant_id=?").get(id))});
}

async function createCase({req,res,db,config,session}){
  const user=requireRole(session,"customer"),body=await readJson(req,config.bodyLimit);
  exactObject(body,["orderId","reason","itemIds","description"]);
  if(!["missing_items","incorrect_items","quality","non_delivery","other"].includes(body.reason))throw new HttpError(400,"VALIDATION_ERROR","Reason is invalid");
  const description=text(body.description,1,1000,"Description"),order=db.prepare("SELECT * FROM orders WHERE id=? AND customer_id=?").get(body.orderId,user.id);
  if(!order)throw new HttpError(404,"NOT_FOUND","Resource not found");
  assertCustomerOrderVisible(order,user,config.now());
  const itemIds=body.itemIds??[];
  if(!Array.isArray(itemIds)||itemIds.length>50||new Set(itemIds).size!==itemIds.length||itemIds.some(id=>typeof id!=="string"||!db.prepare("SELECT 1 FROM order_items WHERE id=? AND order_id=?").get(id,order.id)))throw new HttpError(400,"VALIDATION_ERROR","Items are invalid");
  const requestedAmount=itemIds.length?itemIds.reduce((sum,id)=>{const line=db.prepare("SELECT unit_price_minor,quantity FROM order_items WHERE id=? AND order_id=?").get(id,order.id);return sum+line.unit_price_minor*line.quantity;},0):order.total_minor;
  const issueHash=digest({reason:body.reason,itemIds:[...itemIds].sort()}),existing=db.prepare("SELECT * FROM refund_cases WHERE order_id=? AND issue_hash=? AND status NOT IN ('rejected','refunded')").get(order.id,issueHash);
  if(existing)throw new HttpError(409,"CASE_EXISTS","An active case already exists for this issue");
  const created=withTransaction(db,()=>{
    const nowDate=config.now(),now=nowDate.toISOString(),month=londonMonth(nowDate),priorOrders=new Set(db.prepare("SELECT order_id,created_at FROM refund_cases WHERE customer_id=? AND order_id<>?").all(user.id,order.id).filter(row=>londonMonth(new Date(row.created_at))===month).map(row=>row.order_id));
    const id=randomUUID(),reference=`CE-${now.slice(0,10).replaceAll('-','')}-${id.slice(0,8).toUpperCase()}`;
    db.prepare("INSERT INTO refund_cases(id,reference,order_id,restaurant_id,customer_id,status,reason,item_ids,description,issue_hash,requested_amount_minor,approved_amount_minor,remedy,execution_status,execution_operation_id,execution_error,provider_mode,monthly_review_flag,created_at,updated_at) VALUES(?,?,?,?,?,'awaiting_restaurant',?,?,?,?,?,NULL,NULL,NULL,NULL,NULL,NULL,?,?,?)").run(id,reference,order.id,order.restaurant_id,user.id,body.reason,JSON.stringify(itemIds),description,issueHash,requestedAmount,Number(priorOrders.size>0),now,now);
    db.prepare("INSERT INTO refund_case_events(id,case_id,actor_user_id,kind,details,created_at) VALUES(?,?,?,?,?,?)").run(randomUUID(),id,user.id,"submitted","{}",now);
    db.prepare("INSERT INTO refund_case_events(id,case_id,actor_user_id,kind,details,created_at) VALUES(?,?,?,?,?,?)").run(randomUUID(),id,null,"ask_restaurant",JSON.stringify({restaurantFirst:true}),now);
    for(const member of db.prepare("SELECT user_id FROM restaurant_memberships WHERE restaurant_id=?").all(order.restaurant_id))addNotification(db,{userId:member.user_id,type:"dispute_submitted",title:"Customer reported a problem",message:`Case ${reference} needs a restaurant response.`,orderId:order.id,restaurantId:order.restaurant_id,eventKey:`dispute:${id}:submitted:restaurant:${member.user_id}`,now});
    for(const admin of db.prepare("SELECT id FROM users WHERE role='admin' AND account_enabled=1").all())addNotification(db,{userId:admin.id,type:"dispute_submitted",title:"New dispute case",message:`Case ${reference} is awaiting the restaurant.`,orderId:order.id,restaurantId:order.restaurant_id,eventKey:`dispute:${id}:submitted:admin:${admin.id}`,now});
    const saved=db.prepare("SELECT * FROM refund_cases WHERE id=?").get(id);
    linkOrderHelpToPlatform(db,saved,order,now);
    return saved;
  });
  return sendJson(res,201,{data:caseDto(db,created,"customer")});
}
async function addEvidence({req,res,db,config,session,id}){const a=caseAccess(db,session,id);if(!["customer","admin"].includes(a.u.role)&&a.member?.permission!=="owner")throw new HttpError(403,"OWNER_REQUIRED","Owner permission required");const image=decodeImage(await readJson(req,1_450_000)),now=nowIso(config),eid=randomUUID(),del=new Date(config.now().getTime()+90*86400000).toISOString();db.prepare("INSERT INTO refund_case_evidence VALUES(?,?,?,?,?,?,?,?)").run(eid,id,a.u.id,image.mimeType,image.data,image.data.length,now,del);return sendJson(res,201,{data:{id:eid,mimeType:image.mimeType,byteLength:image.data.length,url:`/api/refund-cases/${id}/evidence/${eid}`,createdAt:now}});}
