async function caseAction({req,res,db,config,session,id}){const u=requireRole(session,"admin"),b=await readJson(req,config.bodyLimit);exactObject(b,["action","message"]);const states={under_review:"under_review",request_information:"awaiting_customer",ask_restaurant:"awaiting_restaurant",internal_note:null,reopen:"under_review"};if(!(b.action in states))throw new HttpError(400,"VALIDATION_ERROR","Action is invalid");const message=text(b.message,1,1000,"Message"),now=nowIso(config);withTransaction(db,()=>{const c=db.prepare("SELECT * FROM refund_cases WHERE id=?").get(id);if(!c)throw new HttpError(404,"NOT_FOUND","Resource not found");if(["refund_processing","awaiting_cash_return","refunded"].includes(c.status)&&b.action!=="internal_note")throw new HttpError(409,"INVALID_CASE_STATE","Case state cannot be regressed");const audience=b.action==="internal_note"?"internal":b.action==="ask_restaurant"?"restaurant":"customer";db.prepare("INSERT INTO refund_case_messages VALUES(?,?,?,?,?,?)").run(randomUUID(),id,u.id,audience,message,now);if(b.action==="reopen")db.prepare("UPDATE refund_cases SET status='under_review',resolved_at=NULL,updated_at=? WHERE id=?").run(now,id);else if(states[b.action])db.prepare("UPDATE refund_cases SET status=?,updated_at=? WHERE id=?").run(states[b.action],now,id);db.prepare("INSERT INTO refund_case_events VALUES(?,?,?,?,?,?)").run(randomUUID(),id,u.id,b.action,JSON.stringify({audience}),now);});return sendJson(res,200,{data:caseDto(db,db.prepare("SELECT * FROM refund_cases WHERE id=?").get(id),"admin")});}
