function applyRefund(db,c,order,op,now,mode="simulated_card"){
  if(db.prepare("SELECT 1 FROM refunds WHERE id=?").get(`case-${c.id}`))return;
  const existing=db.prepare("SELECT COALESCE(SUM(food_amount_minor),0)food,COALESCE(SUM(delivery_amount_minor),0)delivery FROM refunds WHERE order_id=?").get(order.id),amount=c.approved_amount_minor;
  const food=Math.min(amount,Math.max(0,order.subtotal_minor-existing.food)),delivery=Math.min(amount-food,Math.max(0,order.delivery_fee_minor-existing.delivery));
  const baseBefore=order.subtotal_minor-existing.food+((order.commission_base??"food")==="food_plus_delivery"?order.delivery_fee_minor-existing.delivery:0),baseAfter=baseBefore-food-((order.commission_base??"food")==="food_plus_delivery"?delivery:0);
  const reversal=calculateCommissionAtRate(baseBefore,order.contract_rate_bps)-calculateCommissionAtRate(baseAfter,order.contract_rate_bps);
  db.prepare("INSERT INTO refunds VALUES(?,?,?,?,?,?,?,?,?,?,?)").run(`case-${c.id}`,order.id,c.customer_id,`case-${c.id}`,digest({caseId:c.id,amount}),food,delivery,`Refund case ${c.reference}`,mode,reversal,now);
  if(reversal){const kind=order.payment_method==="cash"?"commission_cash_refund":order.payment_method==="card"?"commission_stripe_refund":"commission_mock_refund";db.prepare("INSERT OR IGNORE INTO ledger_entries VALUES(?,?,?,?,?,?,?,?,?)").run(randomUUID(),order.id,order.restaurant_id,kind,-reversal,"GBP","refund_case",c.id,now);}
  const totals=db.prepare("SELECT COALESCE(SUM(food_amount_minor),0)food,COALESCE(SUM(delivery_amount_minor),0)delivery FROM refunds WHERE order_id=?").get(order.id),full=totals.food===order.subtotal_minor&&totals.delivery===order.delivery_fee_minor,status=order.payment_method==="cash"?(full?"cash_refunded":"cash_partially_refunded"):order.payment_method==="card"?(full?"stripe_refunded":"stripe_partially_refunded"):(full?"mock_refunded":"mock_partially_refunded");
  db.prepare("UPDATE orders SET payment_status=?,updated_at=? WHERE id=?").run(status,now,order.id);postBalanced(db,op,"refunds","customer_funds",amount,"refund_case",c.id,now);
  const payout=db.prepare("SELECT p.* FROM payout_batches p JOIN payout_items i ON i.payout_id=p.id JOIN marketplace_operations m ON m.id=i.operation_id WHERE m.order_id=? ORDER BY p.created_at DESC LIMIT 1").get(order.id),merchantRecovery=Math.max(0,amount-reversal);
  if(payout&&["scheduled","pending"].includes(payout.status)){db.prepare("UPDATE payout_batches SET amount_minor=MAX(0,amount_minor-?),updated_at=? WHERE id=?").run(merchantRecovery,now,payout.id);db.prepare("UPDATE payout_items SET amount_minor=MAX(0,amount_minor-?) WHERE payout_id=?").run(merchantRecovery,payout.id);}
  else if(payout?.status==="paid"&&merchantRecovery){const recovery=addOperation(db,{operationKey:`refund-case:${c.id}:transfer-reversal`,restaurantId:order.restaurant_id,orderId:order.id,kind:"transfer_reversal",status:"confirmed",amountMinor:merchantRecovery,now,metadata:{payoutId:payout.id,simulation:true}});postBalanced(db,recovery,"merchant_recovery","provider_funds",merchantRecovery,"refund_case",c.id,now);}
  notifyOrderStatus(db,db.prepare("SELECT * FROM orders WHERE id=?").get(order.id),"refunded",now,"order_refund",`:case-${c.id}`);
}
export function finalizeStripeRefund(db,{caseId,providerReference,now}){const c=db.prepare("SELECT * FROM refund_cases WHERE id=?").get(caseId),order=c&&db.prepare("SELECT * FROM orders WHERE id=? AND payment_method='card'").get(c.order_id);if(!c||!order||c.execution_status==="confirmed")return c;const operationKey=`refund-case:${c.id}:stripe`,op=db.prepare("SELECT * FROM marketplace_operations WHERE operation_key=?").get(operationKey)??addOperation(db,{operationKey,restaurantId:c.restaurant_id,orderId:c.order_id,kind:"order_refund",status:"pending",amountMinor:c.approved_amount_minor,providerMode:db.prepare("SELECT provider_mode FROM stripe_order_payments WHERE order_id=?").get(order.id)?.provider_mode??"stripe_test",now,metadata:{caseReference:c.reference}});db.prepare("UPDATE marketplace_operations SET status='confirmed',provider_reference=?,error=NULL,updated_at=? WHERE id=?").run(providerReference,now,op.id);applyRefund(db,c,order,{...op,status:"confirmed",provider_reference:providerReference},now,"stripe_card");db.prepare("UPDATE refund_cases SET status='refunded',execution_status='confirmed',execution_operation_id=?,execution_error=NULL,updated_at=? WHERE id=?").run(op.id,now,c.id);db.prepare("INSERT INTO refund_case_events(id,case_id,actor_user_id,kind,details,created_at) VALUES(?,?,NULL,'refund_confirmed',?,?)").run(randomUUID(),c.id,JSON.stringify({operationId:op.id,providerReference}),now);return db.prepare("SELECT * FROM refund_cases WHERE id=?").get(c.id);}
export function queueStripeTransferReversal(db,{caseId,now}){const c=db.prepare("SELECT * FROM refund_cases WHERE id=? AND execution_status='confirmed'").get(caseId);if(!c)return null;const transfer=db.prepare("SELECT * FROM marketplace_operations WHERE order_id=? AND kind='merchant_transfer' AND status='confirmed' AND provider_reference IS NOT NULL ORDER BY created_at DESC LIMIT 1").get(c.order_id);if(!transfer||transfer.provider_mode!==c.provider_mode)return null;const snapshot=json(transfer.metadata,{});if(snapshot.refundIds?.includes(`case-${c.id}`))return null;const refund=db.prepare("SELECT * FROM refunds WHERE id=?").get(`case-${c.id}`),amount=Math.max(0,(refund?.food_amount_minor??0)+(refund?.delivery_amount_minor??0)-(refund?.commission_reversal_minor??0));if(!amount)return null;const operationKey=`refund-case:${c.id}:transfer-reversal`,op=addOperation(db,{operationKey,restaurantId:c.restaurant_id,orderId:c.order_id,kind:"transfer_reversal",status:"pending",amountMinor:amount,providerMode:transfer.provider_mode,now,metadata:{caseId:c.id,transferOperationId:transfer.id}});db.prepare("INSERT OR IGNORE INTO marketplace_worker_jobs(id,kind,entity_id,operation_key,status,lease_owner,lease_expires_at,attempts,payload,error,available_at,created_at,updated_at) VALUES(?,?,?,?,'queued',NULL,NULL,0,?,NULL,?,?,?)").run(randomUUID(),"stripe_transfer_reversal",c.id,operationKey,JSON.stringify({caseId:c.id,transferId:transfer.provider_reference,amountMinor:amount,idempotencyKey:operationKey}),now,now,now);return op;}
export function runMarketplaceWorker(db,config,{workerId=randomUUID(),limit=25}={}){
  const now=nowIso(config),lease=new Date(config.now().getTime()+30000).toISOString();
  const terminalized=withTransaction(db,()=>{
    const exhausted=db.prepare("SELECT * FROM marketplace_worker_jobs WHERE kind IN ('refund_execution','transfer_eligibility','report_generation','cash_collection_reconcile','payout_reconcile') AND status='claimed' AND lease_expires_at<=? AND attempts>=3").all(now);
    for(const job of exhausted){
      db.prepare("UPDATE marketplace_worker_jobs SET status='failed',error='Worker lease expired after retry limit',lease_owner=NULL,lease_expires_at=NULL,updated_at=? WHERE id=? AND status='claimed' AND lease_expires_at<=? AND attempts>=3").run(now,job.id,now);
      if(job.kind==="refund_execution")db.prepare("UPDATE refund_cases SET status='refund_failed',execution_status='failed',execution_error='Refund execution failed',updated_at=? WHERE id=? AND status NOT IN ('refunded','rejected')").run(now,job.entity_id);
      if(job.kind==="payout_reconcile")db.prepare("UPDATE payout_batches SET status='failed',failure='Simulated payout reconciliation failed',updated_at=? WHERE id=? AND status<>'paid'").run(now,job.entity_id);
    }
    return exhausted.length;
  });
  const claimed=withTransaction(db,()=>{
    const candidates=db.prepare("SELECT * FROM marketplace_worker_jobs WHERE kind IN ('refund_execution','transfer_eligibility','report_generation','cash_collection_reconcile','payout_reconcile') AND ((status IN ('queued','delayed') AND available_at<=?) OR (status='claimed' AND lease_expires_at<=?)) AND attempts<3 ORDER BY created_at LIMIT ?").all(now,now,limit);
    for(const row of candidates) db.prepare("UPDATE marketplace_worker_jobs SET status='claimed',lease_owner=?,lease_expires_at=?,attempts=attempts+1,updated_at=? WHERE id=? AND ((status IN ('queued','delayed') AND available_at<=?) OR (status='claimed' AND lease_expires_at<=?)) AND attempts<3").run(workerId,lease,now,row.id,now,now);
    return db.prepare("SELECT * FROM marketplace_worker_jobs WHERE lease_owner=? AND status='claimed'").all(workerId);
  });
  let completed=0,failed=terminalized,retried=0;
  for(const job of claimed){
    try{
      withTransaction(db,()=>{
        const ownership=db.prepare("SELECT 1 FROM marketplace_worker_jobs WHERE id=? AND status='claimed' AND lease_owner=?").get(job.id,workerId);
        if(!ownership)throw Error("Marketplace worker lease is no longer owned");
        if(job.kind==="refund_execution") executeRefundJob(db,job,now);
        else if(job.kind==="transfer_eligibility") scheduleSimulatedPayout(db,job,now);
        else if(job.kind==="report_generation") generateReport(db,job,now);
        else if(job.kind==="cash_collection_reconcile") reconcileCashCollection(db,job,now);
        else if(job.kind==="payout_reconcile") reconcileSimulatedPayout(db,job,now);
        else throw Error("Unknown marketplace worker job kind");
        db.prepare("UPDATE marketplace_worker_jobs SET status='completed',lease_owner=NULL,lease_expires_at=NULL,updated_at=? WHERE id=? AND lease_owner=?").run(now,job.id,workerId);
      });
      completed++;
    }catch{
      const permanent=job.attempts>=3,next=new Date(config.now().getTime()+Math.min(60,2**job.attempts)*60000).toISOString();
      withTransaction(db,()=>{
        db.prepare("UPDATE marketplace_worker_jobs SET status=?,error='Worker execution failed',lease_owner=NULL,lease_expires_at=NULL,available_at=?,updated_at=? WHERE id=? AND lease_owner=?").run(permanent?"failed":"delayed",permanent?now:next,now,job.id,workerId);
        if(job.kind==="refund_execution")db.prepare("UPDATE refund_cases SET status=?,execution_status=?,execution_error='Refund execution failed',updated_at=? WHERE id=? AND status NOT IN ('refunded','rejected')").run(permanent?"refund_failed":"refund_processing",permanent?"failed":"retrying",now,job.entity_id);
        if(job.kind==="payout_reconcile"&&permanent)db.prepare("UPDATE payout_batches SET status='failed',failure='Simulated payout reconciliation failed',updated_at=? WHERE id=? AND status<>'paid'").run(now,job.entity_id);
      });
      if(permanent)failed++;else retried++;
    }
  }
  return{claimed:claimed.length,completed,failed,retried};
}
function executeRefundJob(db,job,now){
  const c=db.prepare("SELECT * FROM refund_cases WHERE id=?").get(job.entity_id),order=c&&db.prepare("SELECT * FROM orders WHERE id=?").get(c.order_id);
  if(!c||!order)throw Error("Missing refund case");
  if(order.payment_method==="card")throw Error("Stripe refunds require the Stripe worker");
  const op=addOperation(db,{operationKey:`refund-case:${c.id}:provider`,restaurantId:c.restaurant_id,orderId:c.order_id,kind:c.remedy==="goodwill"?"goodwill_refund":"order_refund",status:"confirmed",amountMinor:c.approved_amount_minor,now,metadata:{caseReference:c.reference,simulation:true}});
  applyRefund(db,c,order,op,now);
  db.prepare("UPDATE refund_cases SET status='refunded',execution_status='confirmed',execution_operation_id=?,updated_at=? WHERE id=?").run(op.id,now,c.id);
  db.prepare("INSERT INTO refund_case_events VALUES(?,?,?,?,?,?)").run(randomUUID(),c.id,null,"refund_confirmed",JSON.stringify({operationId:op.id}),now);
}
function scheduleSimulatedPayout(db,job,now){
  const payload=json(job.payload,{}),op=db.prepare("SELECT * FROM marketplace_operations WHERE id=? AND kind='settlement_eligibility' AND status='confirmed'").get(payload.operationId);
  if(!op)return;
  if(op.provider_mode!=="local_simulator"||db.prepare("SELECT 1 FROM orders WHERE id=? AND payment_method='card'").get(op.order_id))throw Error("Stripe transfers cannot enter simulated payouts");
  const payoutId=randomUUID(),scheduled=new Date(Date.parse(now)+7*86400000).toISOString();
  db.prepare("INSERT OR IGNORE INTO payout_batches(id,restaurant_id,operation_key,status,amount_minor,provider_mode,scheduled_for,provider_reference,failure,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?)").run(payoutId,op.restaurant_id,`payout:${op.order_id}`,"scheduled",op.amount_minor,"local_simulator",scheduled,null,null,now,now);
  const payout=db.prepare("SELECT * FROM payout_batches WHERE operation_key=?").get(`payout:${op.order_id}`);
  db.prepare("INSERT OR IGNORE INTO payout_items VALUES(?,?,?)").run(payout.id,op.id,op.amount_minor);
  db.prepare("INSERT OR IGNORE INTO marketplace_worker_jobs(id,kind,entity_id,operation_key,status,lease_owner,lease_expires_at,attempts,payload,error,available_at,created_at,updated_at) VALUES(?,?,?,?,'delayed',NULL,NULL,0,?,NULL,?,?,?)").run(randomUUID(),"payout_reconcile",payout.id,`payout-reconcile:${payout.id}:transfer`,JSON.stringify({payoutId:payout.id}),scheduled,now,now);
}
function reconcileSimulatedPayout(db,job,now){
  const payout=db.prepare("SELECT * FROM payout_batches WHERE id=?").get(job.entity_id);if(!payout||["paid","failed","held"].includes(payout.status))return;
  if(payout.status==="scheduled"){
    const reference=`sim_tr_${digest(payout.id).slice(0,24)}`,op=addOperation(db,{operationKey:`payout:${payout.id}:transfer`,restaurantId:payout.restaurant_id,kind:"merchant_transfer",status:"confirmed",amountMinor:payout.amount_minor,now,metadata:{payoutId:payout.id,simulation:true,stage:"provider_transfer"}});
    postBalanced(db,op,"merchant_available","provider_transit",payout.amount_minor,"payout",payout.id,now);
    db.prepare("UPDATE payout_batches SET status='in_transit',provider_reference=?,failure=NULL,updated_at=? WHERE id=? AND status='scheduled'").run(reference,now,payout.id);
    db.prepare("INSERT OR IGNORE INTO marketplace_worker_jobs(id,kind,entity_id,operation_key,status,lease_owner,lease_expires_at,attempts,payload,error,available_at,created_at,updated_at) VALUES(?,?,?,?,'delayed',NULL,NULL,0,?,NULL,?,?,?)").run(randomUUID(),"payout_reconcile",payout.id,`payout-reconcile:${payout.id}:bank`,JSON.stringify({payoutId:payout.id}),now,now,now);
    return;
  }
  if(payout.status==="in_transit"){
    const op=addOperation(db,{operationKey:`payout:${payout.id}:bank-confirmation`,restaurantId:payout.restaurant_id,kind:"bank_payout_confirmation",status:"confirmed",amountMinor:payout.amount_minor,now,metadata:{payoutId:payout.id,simulation:true,stage:"bank_confirmation"}});
    postBalanced(db,op,"provider_transit","merchant_bank",payout.amount_minor,"payout",payout.id,now);
    db.prepare("UPDATE payout_batches SET status='paid',failure=NULL,updated_at=? WHERE id=? AND status='in_transit'").run(now,payout.id);
  }
}
function generateReport(db,job,now){const payload=json(job.payload,{}),report=db.prepare("SELECT * FROM marketplace_report_jobs WHERE id=?").get(payload.reportId);if(!report)throw Error("Missing report job");const rows=db.prepare("SELECT * FROM marketplace_operations WHERE restaurant_id=? ORDER BY created_at").all(report.restaurant_id).filter(row=>inRange(row,payload.range??{from:null,to:null}));db.prepare("UPDATE marketplace_report_jobs SET status='completed',content=?,error=NULL,updated_at=? WHERE id=? AND status='queued'").run(Buffer.from(statementContent(rows)),now,report.id);}
function reconcileCashCollection(db,job,now){const payload=json(job.payload,{}),row=db.prepare("SELECT * FROM cash_collections WHERE id=?").get(payload.collectionId);if(!row||row.status!=="delayed")return;db.prepare("UPDATE cash_collections SET status='succeeded',failure=NULL,updated_at=? WHERE id=? AND status='delayed'").run(now,row.id);db.prepare("UPDATE marketplace_operations SET status='confirmed',updated_at=? WHERE operation_key=? AND status='delayed'").run(now,row.operation_key);const op=db.prepare("SELECT * FROM marketplace_operations WHERE operation_key=?").get(row.operation_key);postBalanced(db,op,"cash_collection","cash_commission_receivable",row.amount_minor,"cash_collection",row.id,now);}

function receiptV1(db,order){const dto=orderDto(db,order,false,false);return{format:"cal-eats-receipt-v1",orderNumber:dto.id,restaurantName:dto.restaurantName,fulfillment:dto.fulfillment,createdAt:dto.createdAt,customerName:dto.customerName,...(dto.customerPhone?{customerPhone:dto.customerPhone}:{}),...(dto.deliveryAddress?{deliveryAddress:dto.deliveryAddress}:{}),items:dto.items.map(i=>({name:i.name,quantity:i.quantity,unitPriceMinor:i.unitPriceMinor,totalMinor:i.lineTotalMinor,modifiers:i.selectedModifiers.map(x=>({name:x.name,priceMinor:x.priceMinor}))})),...(dto.deliveryInstructions?{orderNotes:dto.deliveryInstructions}:{}),...(dto.allergyNotes?{allergyNotes:dto.allergyNotes}:{}),subtotalMinor:dto.subtotalMinor,deliveryFeeMinor:dto.deliveryFeeMinor,totalMinor:dto.totalMinor,currency:"GBP",paymentStatus:dto.paymentStatus};}
function printerMac(value){
  if(value===undefined||value===null||value==="")return null;
  // Calai's serial_number also accepts a printer serial, not only a MAC.
  // It is display metadata; authentication remains the paired device credential.
  if(typeof value!=="string")throw new HttpError(400,"VALIDATION_ERROR","Enter a MAC address or printer serial number");
  const identifier=text(value.normalize("NFKC"),1,100,"MAC address or serial number");
  const compact=identifier.replace(/[\s:.\-\u2010-\u2015\u2212\u200b-\u200d\u2060\ufeff]/g,"").toUpperCase();
  if(/^[0-9A-F]{12}$/.test(compact))return compact.match(/.{2}/g).join(":");
  if(!/[\p{L}\p{N}]/u.test(identifier)||/[\u0000-\u001f\u007f-\u009f\u200b-\u200f\u202a-\u202e\u2060-\u206f\ufeff]/.test(identifier))throw new HttpError(400,"VALIDATION_ERROR","Enter a MAC address or printer serial number");
  return identifier;
}
function printerIp(value){if(value===undefined||value===null||value==="")return null;const ip=text(value,1,45,"IP address");if(!isIP(ip))throw new HttpError(400,"VALIDATION_ERROR","Enter a valid IPv4 or IPv6 printer address");return ip;}
function assertPrinterMac(db,restaurantId,mac,id=null){if(mac&&db.prepare("SELECT 1 FROM restaurant_printers WHERE restaurant_id=? AND mac_address=? AND revoked_at IS NULL AND id<>?").get(restaurantId,mac,id??""))throw new HttpError(409,"PRINTER_MAC_IN_USE","This MAC address is already assigned to an active printer in this restaurant");}
async function createPrinter({req,res,db,config,session,id}){requireRestaurantOwner(db,session,id);const b=await readJson(req,config.bodyLimit);exactObject(b,["name","enabled","macAddress","ipAddress"]);const name=text(b.name,1,100,"Printer name"),mac=printerMac(b.macAddress),ip=printerIp(b.ipAddress);if(typeof b.enabled!=="boolean")throw new HttpError(400,"VALIDATION_ERROR","Enabled is invalid");const now=nowIso(config),pid=randomUUID();withTransaction(db,()=>{assertPrinterMac(db,id,mac);db.prepare("INSERT INTO restaurant_printers(id,restaurant_id,name,enabled,revoked_at,created_at,updated_at,mac_address,ip_address) VALUES(?,?,?,?,NULL,?,?,?,?)").run(pid,id,name,Number(b.enabled),now,now,mac,ip);});return sendJson(res,201,{data:printerDto(db.prepare("SELECT * FROM restaurant_printers WHERE id=?").get(pid))});}
async function patchPrinter({req,res,db,config,session,restaurantId,id}){requireRestaurantOwner(db,session,restaurantId);const b=await readJson(req,config.bodyLimit);exactObject(b,["name","enabled","revoked","macAddress","ipAddress"]);const row=db.prepare("SELECT * FROM restaurant_printers WHERE id=? AND restaurant_id=?").get(id,restaurantId);if(!row)throw new HttpError(404,"NOT_FOUND","Resource not found");const name=b.name===undefined?row.name:text(b.name,1,100,"Printer name"),mac=b.macAddress===undefined?row.mac_address:printerMac(b.macAddress),ip=b.ipAddress===undefined?row.ip_address:printerIp(b.ipAddress),enabled=b.enabled===undefined?Boolean(row.enabled):b.enabled,revoked=b.revoked===undefined?Boolean(row.revoked_at):b.revoked;if(typeof enabled!=="boolean"||typeof revoked!=="boolean")throw new HttpError(400,"VALIDATION_ERROR","Printer state is invalid");const now=nowIso(config);withTransaction(db,()=>{if(!revoked)assertPrinterMac(db,restaurantId,mac,id);db.prepare("UPDATE restaurant_printers SET name=?,enabled=?,revoked_at=?,updated_at=?,mac_address=?,ip_address=? WHERE id=?").run(name,Number(enabled),revoked?(row.revoked_at??now):null,now,mac,ip,id);if(revoked)db.prepare("UPDATE printer_devices SET revoked_at=? WHERE printer_id=? AND revoked_at IS NULL").run(now,id);});return sendJson(res,200,{data:printerDto(db.prepare("SELECT * FROM restaurant_printers WHERE id=?").get(id))});}
async function downloadPrinterBridge({res,db,config,session,restaurantId,id}){requireRestaurantOwner(db,session,restaurantId);const printer=db.prepare("SELECT * FROM restaurant_printers WHERE id=? AND restaurant_id=? AND revoked_at IS NULL").get(id,restaurantId);if(!printer)throw new HttpError(404,"NOT_FOUND","Resource not found");const zip=await buildPrinterBridgePackage(printer,config.origin);res.writeHead(200,{"Content-Type":"application/zip","Content-Disposition":'attachment; filename="cal-eats-printer-bridge.zip"',"Content-Length":zip.length,"Cache-Control":"private, no-store"});res.end(zip);}
async function pairingCode({req,res,db,config,session,restaurantId,id}){requireRestaurantOwner(db,session,restaurantId);await empty(req,config);const printer=db.prepare("SELECT * FROM restaurant_printers WHERE id=? AND restaurant_id=? AND enabled=1 AND revoked_at IS NULL").get(id,restaurantId);if(!printer)throw new HttpError(404,"NOT_FOUND","Resource not found");const raw=randomBytes(9).toString("base64url").toUpperCase(),now=nowIso(config),expires=new Date(config.now().getTime()+10*60000).toISOString();withTransaction(db,()=>{db.prepare("DELETE FROM printer_pairing_codes WHERE printer_id=? AND consumed_at IS NULL").run(id);db.prepare("INSERT INTO printer_pairing_codes VALUES(?,?,?,?,?,?)").run(randomUUID(),id,digest(raw),expires,null,now);});return sendJson(res,201,{data:{code:raw,expiresAt:expires}});}
function deviceAuth(req,db){const auth=req.headers.authorization??"",token=auth.startsWith("Bearer ")?auth.slice(7):"";if(!token)throw new HttpError(401,"DEVICE_AUTH_REQUIRED","Device authentication required");const d=db.prepare("SELECT d.*,p.enabled,p.revoked_at printer_revoked FROM printer_devices d JOIN restaurant_printers p ON p.id=d.printer_id WHERE d.token_hash=? AND d.revoked_at IS NULL").get(digest(token));if(!d||!d.enabled||d.printer_revoked)throw new HttpError(401,"INVALID_DEVICE_TOKEN","Device token is invalid");return d;}
async function pairDevice({req,res,db,config}){const b=await readJson(req,config.bodyLimit);exactObject(b,["code","name"]);const code=text(b.code,8,100,"Pairing code"),name=text(b.name,1,100,"Device name"),now=nowIso(config),raw=randomBytes(32).toString("base64url");const d=withTransaction(db,()=>{const p=db.prepare("SELECT c.*,p.restaurant_id,p.enabled,p.revoked_at FROM printer_pairing_codes c JOIN restaurant_printers p ON p.id=c.printer_id WHERE c.code_hash=?").get(digest(code));if(!p||p.consumed_at||p.expires_at<=now||!p.enabled||p.revoked_at)throw new HttpError(401,"INVALID_PAIRING_CODE","Pairing code is invalid or expired");const did=randomUUID();db.prepare("UPDATE printer_pairing_codes SET consumed_at=? WHERE id=? AND consumed_at IS NULL").run(now,p.id);db.prepare("INSERT INTO printer_devices VALUES(?,?,?,?,?,NULL,NULL,?)").run(did,p.printer_id,p.restaurant_id,name,digest(raw),now);return{id:did,printerId:p.printer_id,restaurantId:p.restaurant_id};});return sendJson(res,201,{data:{deviceId:d.id,token:raw,restaurantId:d.restaurantId,printerId:d.printerId}});}
async function deviceHeartbeat({req,res,db,config}){const d=deviceAuth(req,db);await empty(req,config);const now=nowIso(config);db.prepare("UPDATE printer_devices SET last_seen_at=? WHERE id=?").run(now,d.id);return sendJson(res,200,{data:{deviceId:d.id,lastSeenAt:now}});}
async function claimJob({req,res,db,config}){const d=deviceAuth(req,db);await empty(req,config);const now=nowIso(config),lease=new Date(config.now().getTime()+30000).toISOString(),raw=randomBytes(32).toString("base64url"),tokenHash=digest(raw);const result=withTransaction(db,()=>{let job=db.prepare("SELECT * FROM device_print_jobs WHERE printer_id=? AND status='claimed' AND lease_expires_at>? AND claimed_by_device_id=? ORDER BY created_at LIMIT 1").get(d.printer_id,now,d.id);if(job){db.prepare("INSERT INTO printer_job_claim_tokens VALUES(?,?,?,?)").run(job.id,d.id,tokenHash,now);return{job,token:raw};}job=db.prepare("SELECT * FROM device_print_jobs WHERE printer_id=? AND (status='queued' OR (status='claimed' AND lease_expires_at<=?)) ORDER BY created_at LIMIT 1").get(d.printer_id,now);if(!job)return null;const changed=db.prepare("UPDATE device_print_jobs SET status='claimed',attempt=attempt+1,claim_token_hash=?,lease_expires_at=?,claimed_by_device_id=?,updated_at=? WHERE id=? AND (status='queued' OR (status='claimed' AND lease_expires_at<=?))").run(tokenHash,lease,d.id,now,job.id,now);if(!changed.changes)return null;db.prepare("INSERT INTO printer_job_claim_tokens VALUES(?,?,?,?)").run(job.id,d.id,tokenHash,now);return{job:db.prepare("SELECT * FROM device_print_jobs WHERE id=?").get(job.id),token:raw};});if(!result)return sendJson(res,200,{data:{job:null}});return sendJson(res,200,{data:{job:{id:result.job.id,claimToken:result.token,leaseExpiresAt:result.job.lease_expires_at,attempt:result.job.attempt,receipt:json(result.job.receipt,{}),manualReprint:Boolean(result.job.manual_reprint)}}});}
async function ackJob({req,res,db,config,id}){const d=deviceAuth(req,db),b=await readJson(req,config.bodyLimit);exactObject(b,["claimToken","outcome","detail"]);if(!["printed","failed","uncertain"].includes(b.outcome))throw new HttpError(400,"VALIDATION_ERROR","Outcome is invalid");const token=text(b.claimToken,20,200,"Claim token"),detail=b.detail===undefined?null:text(b.detail,0,500,"Detail"),now=nowIso(config),tokenHash=digest(token);const job=withTransaction(db,()=>{const r=db.prepare("SELECT * FROM device_print_jobs WHERE id=? AND printer_id=?").get(id,d.printer_id);if(!r)throw new HttpError(404,"NOT_FOUND","Resource not found");const issued=db.prepare("SELECT 1 FROM printer_job_claim_tokens WHERE job_id=? AND device_id=? AND token_hash=?").get(id,d.id,tokenHash);if(!issued)throw new HttpError(401,"INVALID_CLAIM_TOKEN","Claim token is invalid");if(["printed","failed","uncertain"].includes(r.status)){if(r.status===b.outcome)return r;throw new HttpError(409,"JOB_ALREADY_ACKNOWLEDGED","Print job was already acknowledged");}db.prepare("UPDATE device_print_jobs SET status=?,detail=?,lease_expires_at=NULL,updated_at=? WHERE id=?").run(b.outcome,detail,now,id);return db.prepare("SELECT * FROM device_print_jobs WHERE id=?").get(id);});return sendJson(res,200,{data:{id:job.id,status:job.status,detail:job.detail}});}
async function reprint({req,res,db,config,session,restaurantId,id}) {
  requireRestaurantOwner(db,session,restaurantId);
  const body=await readJson(req,config.bodyLimit);exactObject(body,["orderId"]);
  const printer=db.prepare("SELECT * FROM restaurant_printers WHERE id=? AND restaurant_id=? AND revoked_at IS NULL").get(id,restaurantId);
  const order=db.prepare("SELECT * FROM orders WHERE id=? AND restaurant_id=?").get(body.orderId,restaurantId);
  if(!printer||!order)throw new HttpError(404,"NOT_FOUND","Resource not found");
  if(!printer.enabled)throw new HttpError(409,"PRINTER_DISABLED","Enable this printer before requesting a reprint");
  if(!["accepted","preparing","ready","out_for_delivery","completed"].includes(order.status))throw new HttpError(409,"ORDER_NOT_CONFIRMED","Only confirmed orders can be reprinted");
  const now=nowIso(config),jobId=randomUUID();
  db.prepare("INSERT INTO device_print_jobs(id,printer_id,order_id,operation_key,receipt,status,manual_reprint,attempt,created_at,updated_at) VALUES(?,?,?,?,?,'queued',1,0,?,?)").run(jobId,id,order.id,`order:${order.id}:printer:${id}:reprint:${jobId}`,JSON.stringify(receiptV1(db,order)),now,now);
  return sendJson(res,201,{data:{id:jobId,status:"queued",manualReprint:true}});
}
async function preparation({req,res,db,config,session,id}){
  const body=await readJson(req,config.bodyLimit);exactObject(body,["estimatedReadyAt"]);
  if(typeof body.estimatedReadyAt!=="string")throw new HttpError(400,"VALIDATION_ERROR","Customer ETA is required");
  const access=authorizedOrder(db,session,id),user=requireRestaurantMembership(db,session,access.row.restaurant_id),estimate=resolveConfirmationEta(db,access.row,body.estimatedReadyAt,config);
  withTransaction(db,()=>{
    const order=db.prepare("SELECT * FROM orders WHERE id=?").get(id);
    requireRestaurantMembership(db,session,order.restaurant_id);
    if(!["accepted","preparing"].includes(order.status))throw new HttpError(409,"INVALID_TRANSITION","Customer ETA cannot be changed for this order");
    if(order.estimated_ready_at===estimate)return;
    const now=nowIso(config),eventId=randomUUID(),display=new Intl.DateTimeFormat("en-GB",{timeZone:"Europe/London",weekday:"short",hour:"2-digit",minute:"2-digit"}).format(new Date(estimate));
    db.prepare("UPDATE orders SET estimated_ready_at=?,updated_at=? WHERE id=?").run(estimate,now,id);
    db.prepare("INSERT INTO order_events VALUES(?,?,?,?,?,?,?)").run(eventId,id,user.id,"customer_eta_updated",order.status,order.status,now);
    addNotification(db,{userId:order.customer_id,type:"order_eta",title:"Estimated time updated",message:`Your estimated ${order.fulfillment==="delivery"?"delivery":"collection"} time is now ${display}.`,orderId:id,restaurantId:order.restaurant_id,eventKey:`order:${id}:eta:${eventId}`,now});
  });
  return sendJson(res,200,{data:orderDto(db,db.prepare("SELECT * FROM orders WHERE id=?").get(id),access.includeLedger,access.includeFinancial,config)});
}
